-- uji-content — esquemas del Tema 1, por sección
-- nodo_id apunta al nodo real de la sección en uji_nodos (imprescindible: es lo que
-- usa el lector para encontrar el esquema correcto). seccion_id es además el número
-- de sección (1-8); 0 significa "todo el tema" (no hay sección 0), para el
-- caso en que seccion_id no admita NULL en tu tabla.
-- NULL en nodo_id queda reservado solo para el esquema del tema completo.
-- Idempotente: borra antes de reinsertar cada bloque, así que se puede repetir sin duplicar.
SET NAMES utf8mb4;

-- Esquema del tema completo
DELETE FROM opouj_wp_uji_esquemas WHERE tema_id = 1 AND nodo_id IS NULL;
INSERT INTO opouj_wp_uji_esquemas (tema_id, seccion_id, nodo_id, contenido_html)
VALUES (1, 0, NULL, '<h2>Tema 1 en síntesis</h2><h3>1.1 – Caracteres Generales</h3><ul><li>Proceso constituyente: 31/10/1978, 6/12/1978, 27/12/1978, 29/12/1978.</li><li>Reformas: 1ª – 27 de agosto de 1992 (activo y pasivo); 2ª – 27 de septiembre de 2011.</li><li>Características: extensa, escrita, rígida, consensuada, popular.</li><li>Estructura: 169 artículos en diez títulos. 4-9-1-1 disposiciones (adicionales, transitorias, derogatoria, final).</li><li>Partes: dogmática – orgánica.</li><li>Historia: 1812, 1834, 1837, 1845, 1868, 1876, 1931, 1978.</li><li>Influencias: Ley Fundamental de Bonn (1949) y Constitución de 1931, con aportaciones italianas, portuguesas y francesas.</li></ul><h3>1.2 – Derechos Fundamentales (Título I – De los derechos y deberes fundamentales, arts. 10-55)</h3><h4>A. Derechos y Libertades (Capítulo Segundo)</h4><ul><li>Sección 1ª: Derechos fundamentales y libertades públicas (arts. 15-29).</li><li>Sección 2ª: Derechos y deberes de los ciudadanos (arts. 30-38).</li><li>Principios rectores de la política social y económica (arts. 39-52).</li><li>Garantías de los derechos (arts. 53-54).</li><li>Suspensión de los derechos (art. 55).</li></ul><h4>B. Derechos de nacionalidad (arts. 11-13, Capítulo Primero)</h4><ul><li>Adquisición por ley, no privación. Doble nacionalidad (art. 11).</li><li>Mayoría de edad a los 18 años (art. 12).</li><li>Derechos de los extranjeros (art. 13): extradición, asilo.</li></ul><h3>1.3 – Tribunal Constitucional (Título IX, arts. 159-165)</h3><ul><li>Ley Orgánica 2/1979, de 3 de octubre, del Tribunal Constitucional.</li><li>12 miembros: 4 por el Congreso, 4 por el Senado, 2 por el Gobierno, 2 por el CGPJ.</li><li>Mandato de 9 años. Se renueva por terceras partes cada tres años.</li></ul><h3>1.4 – Defensor del Pueblo</h3><ul><li>Ley Orgánica 3/1981, de 6 de abril, del Defensor del Pueblo.</li><li>Defiende los derechos y libertades de los españoles.</li><li>Mandato de 5 años, elegido por las Cortes (3/5 Congreso/Senado; si no, en el plazo de un mes, 3/5 Congreso y mayoría absoluta Senado).</li></ul><h3>1.5 – La Corona (Título II, arts. 56-65)</h3><ul><li>Inviolabilidad e irresponsabilidad. Funciones. Sucesión, Regencia, Tutela.</li></ul><h3>1.6 – Poder Judicial (Título VI, arts. 117-127)</h3><ul><li>Garantías de independencia: inamovilidad, potestad única, exclusividad, unidad jurisdiccional.</li><li>CGPJ: 20 miembros por 5 años, nombrados por el Rey. 12 entre Jueces y Magistrados; 8 entre abogados y juristas (4 por el Congreso y 4 por el Senado, mayoría de 3/5).</li><li>Tribunal Supremo. Ministerio Fiscal. Policía Judicial.</li></ul><h3>1.7 – Reforma Constitucional (Título X, arts. 166-169)</h3><ul><li>Reforma ordinaria: 3/5 en Congreso y Senado; si no, Comisión paritaria; si no, mayoría absoluta del Senado y 2/3 del Congreso.</li><li>Reforma agravada (revisión total, o del Título Preliminar, Capítulo 2 Sección 1ª del Título I, o del Título II): 2/3 en ambas Cámaras, disolución de las Cortes, ratificación por 2/3 y aprobación del nuevo texto también por 2/3.</li></ul><h3>1.8 – Economía y Hacienda (Título VII, arts. 128-136)</h3>');

-- Esquema de la sección 5
SET @nodo_seccion_5 := (SELECT id FROM opouj_wp_uji_nodos WHERE tema_id = 1 AND tipo = 'seccion' AND numero = '5');
DELETE FROM opouj_wp_uji_esquemas WHERE tema_id = 1 AND nodo_id = @nodo_seccion_5;
INSERT INTO opouj_wp_uji_esquemas (tema_id, seccion_id, nodo_id, contenido_html)
VALUES (1, 5, @nodo_seccion_5, '<h2>La Corona</h2><ul><li>Se declara al Rey como Jefe del Estado.</li></ul><h3>FUNCIONES SIMBÓLICO – REPRESENTATIVAS</h3><ul><li>Símbolo de la unidad y permanencia del Estado.</li><li>Árbitro y moderador del funcionamiento regular de las instituciones.</li><li>La más alta representación del Estado.</li><li>Su título es el de Rey de España y podrá utilizar los demás que correspondan a la Corona</li></ul><h3>INVIOLABILIDAD – REFRENDO</h3><ul><li>La persona del Rey es inviolable y no está sujeta a responsabilidad</li><li>Sus actos estarán siempre refrendados. Los que los refrenden serán los responsables.</li><li>El Rey, la Reina, sus consortes, el Príncipe heredero o los posibles regentes están exentos de declarar</li></ul><h3>FUNCIONES</h3><ul><li>Sancionar y promulgar leyes.</li><li>Convocar y disolver CG y convocar elecciones.</li><li>Convocar a referéndum.</li><li>Proponer candidato a Presidente y nombrarlo.</li><li>Nombrar al Gobierno.</li><li>Expedir los decretos del Consejo de Ministros.</li><li>Mando supremo FFAA</li><li>Ejercer el derecho de gracia.</li><li>Alto Patronazgo de las Reales Academias.</li><li>Acredita a embajadores y otros diplomáticos.</li><li>Manifestar consentimiento del Estado en Tratados.</li><li>Declarar la guerra y hacer la paz, previa autorización de las CG.</li></ul><h3>SUCESIÓN</h3><ul><li>Hereditaria en los sucesores del Juan Carlos I.</li><li>Orden de primogenitura y representación, preferida la línea anterior a posteriores.</li><li>En la misma línea, el grado más próximo al más remoto, y varón a mujer, en más edad.</li><li>Sin sucesión serán las Cortes las que la proveerán.</li><li>Las abdicaciones y renuncias, y cualquier duda se resolverán por una ley orgánica.</li><li>La Reina consorte o el consorte de la Reina no podrán asumir funciones constitucionales.</li></ul><h3>REGENCIA</h3><ul><li>Si el heredero es menor de edad: Regencia por el pariente de más edad más cerca de la sucesión.</li><li>Si Rey inhabilitado: Regencia por príncipe heredero.</li><li>Si nadie para Regencia: Cortes nombra, 1, 3 o 5 personas.</li><li>Para ejercer la Regencia es preciso ser español y mayor de edad.</li><li>La Regencia será por mandato constitucional y siempre en nombre del Rey.</li></ul><h3>TUTELA</h3><ul><li>Será Tutor la persona nombrada por el Rey en Testamento, si mayor y español.</li><li>Si no se hubiese nombrado: el padre o madre mientras estén viudos.</li><li>En defecto: las Cortes lo nombrarán, pero sólo padre, madre o directos podrán acumular Rg/Tut.</li><li>El ejercicio de la Tutela es incompatible con cualquier cargo o representación política.</li></ul><h3>PROCLAMACIÓN Y JURAMENTO</h3><ul><li>El Rey, proclamado ante las Cortes Generales, prestará juramento.</li><li>El Príncipe heredero, al alcanzar la mayoría de edad, y regente/s, prestarán juramento ante CG.</li></ul>');

-- Esquema de la sección 4
SET @nodo_seccion_4 := (SELECT id FROM opouj_wp_uji_nodos WHERE tema_id = 1 AND tipo = 'seccion' AND numero = '4');
DELETE FROM opouj_wp_uji_esquemas WHERE tema_id = 1 AND nodo_id = @nodo_seccion_4;
INSERT INTO opouj_wp_uji_esquemas (tema_id, seccion_id, nodo_id, contenido_html)
VALUES (1, 4, @nodo_seccion_4, '<h2>El Defensor del Pueblo</h2><ul><li>Ley Orgánica 3/81 de 6 de abril, del Defensor del Pueblo.</li><li>Constitución: artículo 54 del Capítulo 4 del Título I, denominado "de las garantías de las libertades y derechos fundamentales".</li><li>Alto comisionado de las Cortes Generales designado por éstas para la defensa de los derechos comprendidos en el Título I de la Constitución, a cuyo efecto podrá supervisar la actividad de la Administración, dando cuenta a las Cortes Generales.</li><li>Será elegido por las Cortes Generales para un período de cinco años, y se dirigirá a las mismas a través de los Presidentes del Congreso y del Senado, respectivamente.</li></ul><h3>FUNCIONES</h3><ul><li>El Defensor del Pueblo se encarga de defender los derechos y libertades de los españoles, además de la supervisión de las actuaciones de las Administraciones en las relaciones con sus administrados.</li><li>No está sujeto a mandato imperativo ni recibe órdenes de ninguna autoridad, es decir, desempeña sus funciones con total autonomía.</li><li>Goza de inviolabilidad e inmunidad durante el ejercicio de las actuaciones realizadas en el cargo. Y puede interponer recursos de inconstitucionalidad y amparo.</li><li>El Defensor del Pueblo se dirige a las cámaras mediante los presidentes de las mismas. Presenta anualmente informe de las actuaciones realizadas durante el año, pudiendo presentar un informe extraordinario si se tratara de urgente necesidad.</li></ul><h3>ELECCIÓN Y NOMBRAMIENTO</h3><ul><li>Elegido por las Cortes Generales por un período de 5 años con posible reelección.</li><li>Debe ser español, mayor de edad y estar en pleno uso de sus derechos civiles y políticos.</li><li>Selección: Comisión Mixta, 10 días para candidatos; Pleno, 20 días. Votación 3/5.</li><li>Si ninguna propuesta alcanza los 3/5: Comisión Mixta dispone de 1 mes; se exige 3/5 del Congreso y mayoría absoluta del Senado.</li><li>Toma posesión ante las mesas de ambas Cámaras, y los Presidentes del Congreso y del Senado acreditarán con su firma el nombramiento.</li><li>Tiene dos adjuntos y una Secretaría General.</li></ul><h3>CESE</h3><ul><li>Por renuncia, expiración del mandato (reelegible), por condena, por negligencia, o por muerte o incapacidad.</li><li>Si es por renuncia, muerte o expiración del mandato: se declara la vacante y ejercen los adjuntos.</li><li>En los demás casos, las Cortes elegirán al siguiente candidato.</li><li>Incompatibilidades: cualquier cargo, permanencia en activo o filiación.</li></ul><h3>QUEJAS</h3><ul><li>Puede presentar una queja cualquier persona natural o jurídica (y asociaciones) que presente un interés legítimo. No será motivo de restricción la edad, el sexo, la nacionalidad, la incapacidad legal del interesado, el internamiento en un centro penitenciario, etc.</li><li>Requisitos de las quejas: nombre y domicilio, y descripción razonada.</li></ul>');

-- Esquema de la sección 6
SET @nodo_seccion_6 := (SELECT id FROM opouj_wp_uji_nodos WHERE tema_id = 1 AND tipo = 'seccion' AND numero = '6');
DELETE FROM opouj_wp_uji_esquemas WHERE tema_id = 1 AND nodo_id = @nodo_seccion_6;
INSERT INTO opouj_wp_uji_esquemas (tema_id, seccion_id, nodo_id, contenido_html)
VALUES (1, 6, @nodo_seccion_6, '<h2>Poder Judicial</h2><ul><li>Regulado en el Título VI de la CE. Del 117 al 127.</li><li>La justicia emana del pueblo y se administra en nombre del Rey por Jueces y Magistrados integrantes del poder judicial, independientes, inamovibles, responsables y sometidos únicamente al imperio de la ley.</li></ul><h3>GARANTÍAS DE INDEPENDENCIA</h3><ul><li>Inamovilidad: Jueces y Magistrados no podrán ser separados, suspendidos, trasladados ni jubilados sino por ley.</li><li>Potestad única: el ejercicio de la potestad juzgando y haciendo ejecutar lo juzgado corresponde únicamente a Juzgados y Tribunales, según las normas de competencia y procedimiento que las leyes establezcan.</li><li>Exclusividad: no ejercerán más funciones de las señaladas.</li><li>Unidad jurisdiccional: base de la organización y funcionamiento de los Tribunales.</li><li>Obligaciones con la justicia: obligado a cumplir sentencias y demás resoluciones, así como a prestar colaboración.</li></ul><h3>GARANTÍAS DE LOS CIUDADANOS</h3><ul><li>Gratuidad: la Justicia será gratuita cuando así lo disponga la ley, y en todo caso para quienes acrediten insuficiencia de recursos.</li><li>Publicidad: las actuaciones judiciales serán públicas, con las excepciones que se prevean.</li><li>Procedimiento predominantemente oral (en materia criminal). Las sentencias serán siempre motivadas y en audiencia pública.</li><li>Indemnización: derecho a ella por daños de error judicial o por el funcionamiento anormal de la Administración de Justicia.</li></ul><h3>ORGANIZACIÓN – CONSEJO GENERAL DEL PODER JUDICIAL</h3><ul><li>El CGPJ es el órgano de gobierno del Poder Judicial.</li><li>Lo concerniente al Poder Judicial se establecerá por Ley Orgánica.</li><li>Presidente (el mismo que el del Tribunal Supremo) y 20 miembros. Nombrados por el Rey por 5 años.</li><li>12 entre Jueces y Magistrados, por Ley Orgánica.</li><li>4 por el Congreso y 4 por el Senado, entre abogados y juristas, por mayoría de 3/5 (15 años de ejercicio y reconocida competencia).</li></ul><h3>TRIBUNAL SUPREMO</h3><ul><li>En la cúspide del poder judicial. Jurisdicción en todo el territorio nacional.</li><li>Lo componen su Presidente y un número indeterminado de magistrados adscritos a las diversas salas.</li><li>Son nombrados por el Rey a propuesta del CGPJ.</li></ul><h3>MINISTERIO FISCAL</h3><ul><li>Tiene por misión promover la acción de la justicia en defensa de la legalidad, de los derechos de los ciudadanos y del interés público tutelado por la ley, de oficio o a petición de los interesados.</li><li>Actúa por órganos propios, con arreglo a los principios de unidad de actuación y dependencia jerárquica, y con sujeción a los de legalidad e imparcialidad.</li><li>La ley regulará el estatuto orgánico del Ministerio Fiscal.</li><li>El Fiscal General del Estado será nombrado por el Rey, a propuesta del Gobierno, oído el CGPJ.</li></ul><h3>JURADO</h3><ul><li>Los ciudadanos podrán ejercer la acción popular y participar en la Administración de Justicia mediante el Jurado.</li><li>Será con respecto a aquellos procesos penales que la ley determine, así como en los Tribunales tradicionales.</li></ul><h3>POLICÍA JUDICIAL</h3><ul><li>Depende de los Jueces, de los Tribunales y del Ministerio Fiscal, en sus funciones de averiguación del delito y descubrimiento del delincuente.</li></ul><h3>INCOMPATIBILIDADES</h3><ul><li>Los Jueces y Magistrados, así como los Fiscales, mientras se hallen en activo, no podrán desempeñar otros cargos públicos, ni pertenecer a partidos políticos o sindicatos.</li><li>La ley establecerá el sistema y modalidades de asociación profesional de los Jueces, Magistrados y Fiscales.</li><li>La ley establecerá el régimen de incompatibilidades de los miembros del poder judicial, que deberá asegurar la total independencia de los mismos.</li></ul>');

-- Esquema de la sección 8
SET @nodo_seccion_8 := (SELECT id FROM opouj_wp_uji_nodos WHERE tema_id = 1 AND tipo = 'seccion' AND numero = '8');
DELETE FROM opouj_wp_uji_esquemas WHERE tema_id = 1 AND nodo_id = @nodo_seccion_8;
INSERT INTO opouj_wp_uji_esquemas (tema_id, seccion_id, nodo_id, contenido_html)
VALUES (1, 8, @nodo_seccion_8, '<h2>Economía y Hacienda</h2><ul><li>Principio rector: toda la riqueza del país está subordinada al interés general.</li></ul><h3>PRINCIPIOS ECONÓMICOS GENERALES (arts. 128-129)</h3><ul><li>Art. 128 (Iniciativa pública): subordinación de toda la riqueza al interés general. Iniciativa pública en la economía. Posibilidad de reservar al sector público recursos/servicios esenciales (monopolios). Posibilidad de intervención de empresas por interés general.</li><li>Art. 129 (Participación): participación en la Seguridad Social y organismos públicos. Fomento de las cooperativas y del acceso de los trabajadores a la propiedad de los medios de producción.</li></ul><h3>PLANIFICACIÓN Y SECTORES (arts. 130-131)</h3><ul><li>Art. 130 (Modernización): modernización de todos los sectores (especialmente agricultura, pesca y artesanía). Trato especial a las zonas de montaña.</li><li>Art. 131 (Planificación): el Estado puede planificar la economía por ley. Objetivos: atender necesidades colectivas, equilibrar las regiones, lograr una justa distribución de la renta. Elaboración: Gobierno + CC.AA. + Sindicatos + Empresarios. Se crea un Consejo (por ley).</li></ul><h3>BIENES PÚBLICOS Y HACIENDA (arts. 132-133)</h3><ul><li>Art. 132 (Bienes públicos): dominio público inalienable, imprescriptible e inembargable. Son bienes del Estado las playas, el mar territorial, la zona marítimo-terrestre y la plataforma continental. La ley regula el Patrimonio del Estado y el Patrimonio Nacional.</li><li>Art. 133 (Tributos): la potestad originaria corresponde al Estado (mediante ley). Las CC.AA. y CC.LL. pueden establecer tributos según las leyes. Los beneficios fiscales deben establecerse por ley. Los gastos públicos, siempre según las leyes.</li></ul><h3>PRESUPUESTOS GENERALES DEL ESTADO (art. 134)</h3><ul><li>Elaboración: el Gobierno. Aprobación: las Cortes Generales.</li><li>Características: anuales, incluyen todos los gastos e ingresos.</li><li>Prórroga: si no se aprueban antes del 1 de enero, se prorrogan los anteriores.</li><li>Límites al Parlamento: el Gobierno debe autorizar las propuestas que aumenten el gasto o disminuyan los ingresos.</li><li>Relación con los tributos: no puede crear tributos, solo modificarlos si otra ley lo permite.</li></ul><h3>ESTABILIDAD Y DEUDA PÚBLICA (art. 135)</h3><ul><li>Principio rector: la estabilidad presupuestaria.</li><li>Límites: el déficit estructural y la deuda pública, según los márgenes de la UE.</li><li>Entidades locales: equilibrio presupuestario.</li><li>Deuda pública: su emisión necesita autorización por ley.</li><li>Pago de intereses y capital: prioridad absoluta.</li><li>Excepciones: catástrofes, recesión o emergencias (aprobado por mayoría absoluta del Congreso).</li><li>Desarrollo: una Ley Orgánica regulará la distribución de los límites y las responsabilidades.</li></ul><h3>CONTROL ECONÓMICO (art. 136)</h3><ul><li>Órgano fiscalizador: el Tribunal de Cuentas.</li><li>Dependencia: directamente de las Cortes Generales.</li><li>Funciones: examina y censura las cuentas del Estado. Remite un informe anual a las Cortes. Puede señalar infracciones o responsabilidades.</li><li>Miembros: independencia e inamovilidad, como los jueces.</li><li>Regulación: por Ley Orgánica.</li></ul>');

